  AwakerTalent_122607_TalentDesc_1 = {
    Text = "Após jogar 2 cartas \"Golpe\", \"Mouchette\" realiza um seguimento, causando dano aleatoriamente igual a 30% do Ataque de Mouchette, o que é considerado um \"Golpe\". Isso pode ocorrer no máximo 4 vezes por turno."
