  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Este talento só é eficaz nos estágios \"Reinado Astral\".\nA Constituição, Força de ataque e Defesa deste Corpo Desperto +[Arg1]%, e ele ganha [Arg2] Energia da Chave de Prata no primeiro Despertar do Conhecimento Espiritual.\nO Efeito de Gatilho de Envenenamento de todos os Corpos Despertos +[Arg3]%. \nCada acúmulo de \"Embriagado\" reduz adicionalmente o Dano causado por inimigos \"Humanoides\" em 1%, e quando \"Embriagado\" é removido, cada acúmulo causa Dano Fixo igual a 1% da Vida máxima do alvo em inimigos \"Humanoides\"."
  },
