  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Quando Arachne está na equipe, o Domínio Ultra se retece em Singularidade: Ultra.\nLançadeira Dimensional: Após jogar a primeira Carta de comando a cada turno, uma cópia Nada e Cópia Original dela será colocada no Espaço Hiperdimensional e receberá 25 capas de Faro de Singularidade. Isso não pode ser acionado durante Turnos Ultra. Se uma carta acionar a Lançadeira Dimensional, ela também se beneficia dos efeitos do Faro de Singularidade.\nFaro de Singularidade: Para cada capa, o Dano Final de uma carta, ganho de Força e dano de tentáculo Fixo, Envenenamento Fixo e Contador cada +2%; Escudo Final, Recuperar vida e Redução de força cada +1%. Este efeito é limpo quando a carta é jogada. Cartas com este efeito não podem acionar a Lançadeira Dimensional.\nEspaço Hiperdimensional: Quando cheio, iniciar o Turno Ultra não encerra o turno nem inicia um novo; descarte todas as cartas que não sejam Preservar, resolva seus efeitos de Nada, puxe todas as cartas do Espaço Hiperdimensional e defina o Poder de cálculo para 5. O turno atual continua como um Turno Ultra.\nAniquilação da Singularidade: Puxe a carta mais à esquerda do Espaço Hiperdimensional para a mão. Recarga de 3 turnos.\nNo início da investigação, ganhe +50% de Dano potencializado e 15 capas de Prisma da Singularidade.\nPrisma da Singularidade: Os efeitos de todas as Cartas de comando aumentam como se tivessem este número de capas de Faro de Singularidade.\nUltra Mastery: Para cada 1 ponto de Domínio de área, as capas de Faro de Singularidade do Prisma da Singularidade e da Lançadeira Dimensional aumentam em 0,05%.\nUltra Puro: Se a equipe for composta apenas de Corpos Despertos Ultra ou do Caos, o efeito de Ultra Mastery e o Dano potencializado do Domínio são dobrados."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Fios do destino"
  },
  AwakerTalent_130395_TalentDesc_1 = {
