  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\nA Constituição, Força de ataque e Defesa deste Corpo Desperto +[Arg1]%, e ele ganha [Arg2] Energia da Chave de Prata após Disparar o Despertar do Conhecimento Espiritual pela primeira vez.\nO Corpo Desperto selecionado pela \"Canção de Saya\" ganha [Arg3] capas de \"Festa de Propagação\", e faz a próxima Ordem de chave ser ativada 2 vezes.\nSaya inflige +[Arg4]% de Corrosão adicional em inimigos de \"Carne e sangue\"."
  },
