  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·Este Talento só entra em vigor nos níveis do \"Capítulo Estelar\".\n·A Constituição, Ataque e Defesa deste Corpo Desperto aumentam em [Arg1]%, e após o primeiro Despertar do Conhecimento Espiritual disparado por este Corpo Desperto, ele obtém [Arg2] pontos de Energia da Chave de Prata.\n·\"Sombra Selvagem Sem Limites\" causa Efeito de Redução de força, o multiplicador de força obtido aumenta em [Arg3]%, e cada vez que o Efeito é ativado, o próximo \"Ponta de Lança Manchada pelo Pecado\" recebe um bônus de força adicional de [Arg4]%, com limite máximo de 1200%."
  },
  AwakerTalent_130400_TalentDesc_10 = {
    Text = "·Este Talento só entra em vigor nos níveis do \"Capítulo Estelar\".\n·A Constituição, Ataque e Defesa deste Corpo Desperto aumentam em [Arg1]%, e após o primeiro Despertar do Conhecimento Espiritual disparado por este Corpo Desperto, ele obtém [Arg2] pontos de Energia da Chave de Prata.\n·\"Sombra Selvagem Sem Limites\" causa Efeito de Redução de força, o multiplicador de força obtido aumenta em [Arg3]%, e cada vez que o Efeito é ativado, o próximo \"Ponta de Lança Manchada pelo Pecado\" recebe um bônus de força adicional de [Arg4]%, com limite máximo de 1200%."
  },
