    Text = "Este talento só é eficaz nos estágios \"Reinado Astral\".\nA Constituição, Força de ataque e Defesa deste Corpo Desperto +[Arg1]%, e ele ganha [Arg2] Energia da Chave de Prata no primeiro Despertar do Conhecimento Espiritual.\nDano Fixo Base de \"Vórtice! Fluxo! Bala!\" +[Arg3]%.\nO Mosk remove os efeitos de \"Reforço\" e \"Reforço Temporário\" do alvo antes de desencadear a Fúria Explosiva; se removidos com sucesso, o Dano crítico desta Fúria Explosiva +[Arg4]%."
