  AwakerTalent_131854_TalentDesc_1 = {
    Text = "Quando Saya está na equipe, o Domínio de Carne e Sangue se transforma em Reprodução·carne.\n\nFusão de embriões: A Fusão de embriões ganha por turno aumenta para 50~100, escalando com a Vida perdida. O limite de Fusão de embriões aumenta de 100 para 200. Ao atingir o limite, adicione 1 \"Embrião Propágulo\" na mão.\n\nEmbrião Propágulo: Jogar esta carta não concede mais Taxa de Crítico. Devorar não concede mais Escudo ou Força temporária. A primeira vez que cada Corpo Desperto consome um \"Embrião Propágulo\" por turno, ele ganha 40 capas de \"Festa de Propagação\": Cada capa aprimora os seguintes efeitos Finais da próxima Fúria Explosiva daquele Corpo Desperto neste turno em 1%: Dano Final, Escudo Fixo, Recuperação de vida Fixa, Força Fixa/Redução de força, Aumento de dano de tentáculo, Envenenamento Fixo e Contrataque Fixo.\n\nForno Carmesim: O acúmulo automático Em início de turno muda para 10% da Vida perdida, até 50% da Vida máxima. Não acumula mais no final da batalha. Recarga de 3 turnos.\n\nErosão Escarlate: Após usar o Forno Carmesim, inflige Corrosão em todos os inimigos igual a 1% de sua Vida máxima. Quanto mais Forno Carmesim consumido, mais forte o efeito de Corrosão, até +100%. Causa efeito de Corrosão 5× contra inimigos \"Casca vazia\".\n\nNo início da exploração, Vida máxima +10%, Dano potencializado da equipe +50%, e todos os Corpos Despertos ganham 20 capas de \"Festa de Propagação\" Em início de turno. Se a equipe for composta apenas de Corpos Despertos de Carne e sangue ou Caos, o Dano potencializado concedido por este efeito é dobrado.\nO Domínio de área torna-se \"Domínio de Reprodução·carne\": Cada ponto de Domínio de área aumenta as capas de \"Festa de Propagação\" ganhas de \"Reprodução·carne\" em 0,05%.\n\nSe a equipe for composta apenas de Corpos Despertos de Carne e sangue ou Caos, o efeito de \"Domínio de Reprodução·carne\" é dobrado."
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "Reprodução·carne"
  },
