  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nas Fases do \"Capítulo das Estrelas\". \n·A Constituição, o ATQ e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto Disparar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·O Dano Fixo causado por \"Pontos\" aos \"Parentes do Êxtase\" aumenta em [Arg3]%.\n·\"Caçada Implacável\" obtém Dano de tentáculo igual a [Arg4]% da Força de ataque para cada 10 pontos de Fúria consumidos. Quando \"Devastação Gaunt\" causa Dano, também reduz temporariamente a FOR do alvo em [Arg5]% da Defesa."
  },
  AwakerTalent_141303_TalentDesc_10 = {
    Text = "·Este talento só é eficaz nas Fases do \"Capítulo das Estrelas\". \n·A Constituição, o ATQ e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto Disparar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·O Dano Fixo causado por \"Pontos\" aos \"Parentes do Êxtase\" aumenta em [Arg3]%.\n·\"Caçada Implacável\" obtém Dano de tentáculo igual a [Arg4]% da Força de ataque para cada 10 pontos de Fúria consumidos. Quando \"Devastação Gaunt\" causa Dano, também reduz temporariamente a FOR do alvo em [Arg5]% da Defesa."
  },
