  AwakerTalent_143615_TalentDesc_1 = {
    Text = "Quando este personagem está na equipe, o Domínio Mar Profundo se transforma no Domínio \"Benthos: Aequor\".\n\nO Dano de tentáculo base é alterado para 5% da Vida máxima da equipe.\n\nDano potencializado da equipe +50% após o início da exploração (Efeito dobrado se a equipe for composta inteiramente por Corpos Despertos do Mar Profundo e do Caos, embora nenhum tentáculo inicial adicional seja obtido).\nO efeito de Reunião de tentáculos é removido.\nA Postura de Tentáculo muda para \"Benthos: Postura de Tentáculo\".\n\n\"Benthos: Mar Calmo\": Gera imediatamente um Escudo igual a 25% da Vida máxima, e os tentáculos não atacarão mais no fim do turno; recarga de 3 turnos.\n\"Benthos: Mar Tempestuoso\": Dano de tentáculo × 125% durante o turno; após causar Dano ativo, 1 tentáculo ataca; perde 1 tentáculo no fim do turno; recarga de 3 turnos.\nO Domínio de área é contabilizado como \"Benthos: Domínio do Mar Profundo\". Cada ponto fornece: Geração de Escudo da Postura Mar Calmo +0,025% de Vida máxima. Dano de tentáculo da Postura Mar Tempestuoso +0,025%.\nO efeito de \"Benthos: Domínio do Mar Profundo\" é dobrado se a equipe for composta inteiramente por Corpos Despertos do Mar Profundo e do Caos."
  },
  AwakerTalent_143615_TalentName_1 = {
    Text = "Terra Sombria Eterna"
  },
