  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Este Talento só tem efeito nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, o Ataque e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto usar Despertar pela primeira vez, ele ganha [Arg2] de Energia de chave.\n·\"Espada Cortadora de Fronteiras\" recebe um Bônus de Força adicional de [Arg3]%. Após eliminar um inimigo, ganhe [Arg4] Marcas Negras, que recebem o Bônus de Queda de marca negra de Lotan: Cetarcon. Tem efeito até uma vez por batalha."
  },
