  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Quando Caraboo está na equipe, o Domínio de Carne e Sangue se transforma em Reprodução·carne.\n\nFusão de embriões: A Fusão de embriões ganha por turno aumenta para 50~100, escalando com a Vida perdida. O limite de Fusão de embriões aumenta de 100 para 200. Ao atingir o limite, adicione 1 \"Embrião Propágulo\" na mão.\n\nEmbrião Propágulo: Jogar esta carta não concede mais Taxa de Crítico. Devorar não concede mais Escudo ou Força temporária. A primeira vez que cada Corpo Desperto consome um \"Embrião Propágulo\" por turno, ele ganha 40 capas de \"Festa de Propagação\": Cada capa aprimora os seguintes efeitos Finais da próxima Fúria Explosiva daquele Corpo Desperto neste turno em 1%: Dano Final, Escudo Fixo, Recuperação de vida Fixa, Força Fixa/Redução de força, Aumento de dano de tentáculo, Envenenamento Fixo e Contrataque Fixo.\n\nForno Carmesim: O acúmulo automático Em início de turno muda para 10% da Vida perdida, até 50% da Vida máxima. Não acumula mais no final da batalha. Recarga de 3 turnos.\n\nErosão Escarlate: Após usar o Forno Carmesim, inflige Corrosão em todos os inimigos igual a 1% de sua Vida máxima. Quanto mais Forno Carmesim consumido, mais forte o efeito de Corrosão, até +100%. Causa efeito de Corrosão 5× contra inimigos \"Casca vazia\".\n\nNo início da exploração, Vida máxima +10%, Dano potencializado da equipe +50%, e todos os Corpos Despertos ganham 20 capas de \"Festa de Propagação\" Em início de turno. Se a equipe for composta apenas de Corpos Despertos de Carne e sangue ou Caos, o Dano potencializado concedido por este efeito é dobrado.\nO Domínio de área torna-se \"Domínio de Reprodução·carne\": Cada ponto de Domínio de área aumenta as capas de \"Festa de Propagação\" ganhas de \"Reprodução·carne\" em 0,05%.\n\nSe a equipe for composta apenas de Corpos Despertos de Carne e sangue ou Caos, o efeito de \"Domínio de Reprodução·carne\" é dobrado."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Reprodução·carne"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Quando Lotan: Cetarcon está na equipe, o Domínio do Caos se transforma em Primórdia: Caos.\n\nInfluxo Primordial: A Energia da Chave de Prata base aumenta para 2000, a Potencialização de Dano da equipe aumenta em 50%, e o Força de ataque e Defesa de todos os Corpos Despertos aumentam em 10%. Se a equipe for composta apenas de Corpos de despertar do caos, o bônus de Dano potencializado deste efeito é dobrado. No início da batalha, ganhe 2000 de Energia da Chave de Prata.\n\nChaves Confluentes: Os Níveis de Carga da Chave de Prata de todos os Corpos Despertos são definidos pela média da equipe. Os Corpos Despertos não ganham mais Energia da Chave de Prata pelo Poder de cálculo consumido; em vez disso, a primeira Carta de comando jogada por cada Corpo Desperto por turno concede Energia da Chave de Prata igual a (sua Recarga de Chave de Prata × 3) + 100.\n\nReino Indivisível: Não aciona mais os efeitos de Ultra Puro, Domínio de área Duplo ou Dano potencializado Duplo de outros Domínios.\n\nEco Primordial: As Cartas de Despertar ganham Pronto 1; a Ordem de chave equipada atualmente é automaticamente desencadeada na primeira vez que for jogada a cada turno.\n\nFragmentos de Memória: A Ordem de chave é substituída por Primórdia: Recorrência Dual e Primórdia: Revelação Tríade, e a própria Ordem de chave carregada não pode mais ser desencadeada.\n\n-Primórdia: Recorrência Dual: Descubra 3 Ordens de chave das que estão na mão, depois escolha 1 para desencadear duas vezes.\n-Primórdia: Revelação Tríade: Descubra 3 conjuntos de Ordens de chave das que estão na mão, cada conjunto contendo 3 Ordens de chave diferentes. Escolha um conjunto para desencadear cada Ordem de chave dentro dele uma vez, em sequência.\nAs Ordens de chave presentes em Primórdia: Recorrência Dual e Primórdia: Revelação Tríade são extraídas dos oito tipos de Memória Primordial.\nPrimórdia: Recorrência Dual e Primórdia: Revelação Tríade contam cada uma como desencadear apenas 1 Ordem de chave. Quando seus efeitos forem acionados múltiplas vezes, apenas a primeira Ordem de chave a entrar em vigor é válida.\n\nDominação do Caos Primordial: O Domínio de área torna-se Dominação do Caos Primordial. Cada ponto de Dominação do Caos Primordial aumenta a Potência da Ordem de chave em 0,05%. Cada ponto de Potência da Ordem de chave aumenta o Envenenamento Fixo, Contrataque Fixo, Força Fixo, Cinzas antigas Fixas em 2%, e o Escudo Fixo, Recuperação de vida Fixa, Redução de força Fixa e ganho de Dano de tentáculo, Taxa de Crítico, Dano crítico, Dano potencializado, Domínio de área, Geração de Fúria, Fusão de embriões e Geração de Energia da Chave de Prata em 1%."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Sopro Primordial"
  },
  AwakerTalent_147414_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo Estelar\". \n·A constituição, o ataque e a defesa deste Despertado aumentam em [Arg1]%, e após este Despertado jogar uma carta de Despertar da Gnosis pela primeira vez, ele ganha [Arg2] pontos de energia de prata."
