  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·Por cada 1% de resistência à morte proveniente de Lily, a roda do destino e o Mystik equipados aumentam o escudo base de \"Zona Proibida dos Pântanos Negros\" e \"Defesa Base\" em 0,25%, e a quantidade acumulada de Paciência e seu limite aumentam em 0,25% durante a Batalha do Líder.\n·Quando Lily está na equipe, ao perder 1 ponto de vida, ganha 1 camada de Paciência, e o limite de empilhamento de Paciência é igual à Vida máxima."
  },
