  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·O efeito de recuperação da fornalha fornecido por Salvador recebe o bônus de aumento de recuperação de vida."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Pastor de almas"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·Ramona ganha adicionalmente 2.5 pontos de atributo de carga da chave de prata. Cada nível de taxa de sincronização aumenta Ramona em 0.5 pontos de atributo de carga da chave de prata. \n·Para cada 1 ponto de atributo de nível de carga da chave de prata, o dano básico da \"Espada da Rainha\" aumenta em 1%, e ao disparar, ganha 0.75 de domínio de área temporário."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Resonância do Coração e da Prata"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·Círculo·Ramona ganha 2,5 pontos de carga da Chave de Prata adicionais. Cada nível de Taxa de Sincronização faz com que Círculo·Ramona ganhe 0,5 pontos de carga da Chave de Prata adicionais. \n·Para cada 1 ponto de atributo de carga da Chave de Prata, o efeito de loop de \"Golpe Básico\" faz com que Círculo·Ramona ganhe 0,2% de Taxa de Crítico, e o efeito de loop de \"Defesa Básica\" faz com que Círculo·Ramona ganhe 0,2 de Fúria."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Resonância do Coração e da Prata"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "· Para cada ponto de maestria de reino que Náutilo possui, o dano de contra-ataque de \"Pronto e Ajustado\" aumenta em 0.25%."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "manutenção"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "·Para cada 1% de atributo de dano forte que Nínfea possui, o efeito base de veneno causado por \"O sino da morte ressoa\" e \"Meu próprio funeral\" aumenta em 0,5%."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Impregnação"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "No início da batalha, coloque 1 \"Obsessão\" em sua mão.\nO \"Golpe Básico\" de Miryam recebe um aumento de 50% no Dano de tentáculo.\nPara cada 1% de Dano crítico fornecido por Miryam e sua Roda do destino e Mystik equipados, aumenta em 0,2% a força da Fúria Explosiva, o Dano de tentáculo, a Fúria, a aplicação e a ativação do efeito de Envenenamento."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Devoção Imortal"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·Para cada nível de recarga de loucura fornecido por Tulu, Roda da Vida e Pacto Secreto, \"Golpe Básico\" recebe 5% de bônus no dano de tentáculo e poder, e \"Ordem do Abismo\" recebe 15% de bônus no dano de tentáculo e poder."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Poder do Rei Deus"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "·Sanga, por cada 1% de resistência à morte proveniente de si mesma, da roda do destino e do mystik equipados, aumenta em 0,03 pontos a fúria obtida de \"Golpe Básico\" e \"Defesa Básica\", e \"Arte Perdida\" recebe um bônus adicional de 0,15% em taxa de crítico e dano crítico."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Inspiração da Morte"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "·Para cada nível de taxa de recarga de loucura que a Boneca possuir, o efeito de recuperação de vida de \"Cirurgia no Vazio\" e \"Intercâmbio Equivalente\" aumenta 0,5%."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Dessutura da Gnosis"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "·Para cada 1% de atributo de queda de selo negro que Ogier possuir, o poder temporário obtido por \"Sete artes e virtudes\" aumenta em 3%."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Transmutação sem forma"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·Para cada 1% de atributo de resistência à morte que Alva possui, o dano base aumenta em 0,5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Campo de visão dinâmico"
  },
