  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·Por cada 1% de taxa crítica proveniente de Sorel, roda do destino e pacto equipados, o aliemus obtido a partir da \"defesa base\" aumenta em 0,2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Guardião da Ostentação"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·Por cada 1% de taxa crítica fornecida por Jenkins, roda do destino ou pacto, o dano base de \"golpe básico\" e \"marrom, ataque!\" aumenta em 2%."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Unidos contra o inimigo"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·Por cada 1 ponto de nível de recarga de chave de prata fornecido por Erica, roda do destino ou pacto, \"Explosão Eletromagnética\" concede a Erica 0,5% de taxa crítica temporária e dano crítico."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Fonte de energia externa"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·No início do turno, ganhe 1 camada de Guia de sonhos. \n ·A cada consumo de 1 camada de Guia de sonhos, o ataque potencializado do \"Guardião Perdido\" e \"Cidade dos Sonhos Mortos\" aumenta em 5%. \n ·Para cada 1% de Dano potencializado fornecido pelo próprio Corpo Desperto de Wanda, Roda do destino e Mystik, o ataque potencializado de \"Cidade dos Sonhos Mortos\" aumenta em 0,75%."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Revelação"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·Para cada 1 ponto de Maestria no Reino fornecido pelo despertador Casiah, Roda do Destino e Pacto, \"Carnaval Mágico\" aumenta o dano base de Casiah em 0,2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Mestre de mágica"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·Por cada 1% de atributo de queda de sigilo negro fornecido por Tintin, roda do destino ou pacto, \"Aurora Cromática\" recebe 0,15% adicionais de taxa crítica temporária."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Viajante planetário"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·O \"Golpe Básico\" e a \"Defesa Básica\" de Horla também são considerados um poema. Durante a transição do poema, mudará para diferentes emoções, que podem influenciar diretamente o efeito deste poema. Estar em diferentes emoções trará diferentes efeitos de equipe contínuos. \n·Para cada 1% de Resistência à Morte que Horla possui, o bônus desse efeito aumenta em 0,1% do valor inicial."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Caneta cria sentimentos"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "· Para cada 1% de efeito de Dano Forte que os Faróis têm, o Escudo gerado pela \"A cidade perdida\" aumenta em 0.4%."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Obsessão pelo Retorno à Pátria"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "· Para cada 1% de taxa de queda do O sigilo negro que Caecus possui, o \"Golpe Básico\" recebe um bônus de contador de 1%."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Púas rebeldes"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·Celeste ativa um cartão de comando para disparar 1 tentáculo para atacar os inimigos; para cada 1 ponto de maestria de reino de Celeste, a roda e o pacto, essa ativação causa um dano adicional de 0,5% de tentáculo."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Corneta de Navegação Distante"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·Para cada 1% no atributo de queda de sigilo negro que Salvador possui, o limite da fornalha carmesim aumenta em 0,15% da vida máxima."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Lugar de início"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "Por cada 1% de Queda de marca negra que Agrippa e sua Roda do destino e Mystik equipados possuem, o Escudo Base de \"Abrigo Pálido\" +0,5%, e o Envenenamento Base +1%."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Marca de pacto"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·Para cada 1% de resistência à morte que Faint possuir, aumenta em 0,2% a taxa de retaliatória obtida por \"Berço das Estrelas\" e \"Esplendor Estelar Sem Limites\", e aumenta em 2% o limite de Resistência à Morte de \"Berço das Estrelas\"."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Cradle Secundário"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·Para cada 1% de atributo de dano aumentado que Hilota possuir, \"Sobrevivência em Apuros\" aumenta o dano causado por Hilota neste turno em 0,3%."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Cicatriz de dor"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·Ryker ganha 5 Marca Negra ao eliminar inimigos, e para cada 1% de queda de Marca Negra, a quantidade obtida aumenta em 1%, com um máximo de 5 ativações por exploração. \n·Ao obter 75/150/300 Marca Negra através de combate, o limite de criação aumenta em 1, e ao final da batalha, escolha um <C05_zaowu:\"Legado do Caos\"> para adicionar à lista de criações."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "O vencedor leva tudo"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·Na batalha contra o chefe, no início do turno e após \"Doll em Fusão\" liberar a exaltação, ganhe 1 camada de \"Fim\". \"Fim\" pode acumular no máximo 10 camadas e, ao alcançar 10 camadas, adicione 1 carta de \"Fim do Vazio\" à sua mão."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Caminho da Aniquilação"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto disparar pela primeira vez o Despertar do Conhecimento Espiritual, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·Cada tentáculo que ataca aumenta temporariamente o dano de tentáculo em [Arg3]% da força de ataque de Tulu, podendo ser ativado no máximo [Arg4] vezes por turno.\n·Quando houver 1/2/3 outros Corpos Despertos \"Lemurianos\" na equipe, todos os inimigos recebem 10%/25%/50% mais Dano de tentáculo."
  },
