  AwakerTalent_74100_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O efeito de Redução de força de \"Faint\" é aumentado em [Arg4]%. Após Disparar a Carta de comando de \"Faint\", rouba Temporariamente [Arg3]% da Força de ATQ de Faint de inimigos \"Humanoides\", com efeito máximo de 3 vezes por turno."
