  AwakerTalent_74101_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·A Marca Negra obtida pelo próprio Ryker é aumentada em [Arg4]%, e a Taxa de Crítico é aumentada em [Arg3]%. Se pelo menos 400 Marcas Negras forem obtidas durante a batalha, ao início da batalha, 1 \"Legado do Caos\" é Melhorado."
  },
