  AwakerTalent_74103_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·A primeira \"Remoinho pálido\" Disparada por turno obtém Fusão de embriões+ [Arg3]; após acionar Devorar, o Consumo de potência de cálculo de 1 \"Remoinho pálido\" na Mão é reduzido em 1."
