  AwakerTalent_74105_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·A cada 1 \"Divisão de glândulas\" consumida pelo \"Mar Agitado\", o Dano causado por Aurita no restante desta batalha aumenta em [Arg3]% da Força de ataque. Na Batalha do Líder, se o \"Mar Agitado\" consumiu pelo menos 20 \"Divisão de glândulas\", o número de vezes que \"Divisão de glândulas\" causa Dano ao ser Disparada e consumida é +1. As primeiras [Arg4] \"Divisão de glândulas\" Disparadas por turno não adicionam \"Ajuste de potência de cálculo\"."
  },
