  AwakerTalent_74107_TalentDesc_1 = {
    Text = "·Este talento só tem efeito nas fases do \"Capítulo Stella\".\n·A vitalidade, ataque e defesa do Despertador aumentam em [Arg1] %, e o Despertador ganha [Arg2] pontos de S-energia após seu primeiro Despertar de Gnose.\n·O efeito de veneno desencadeado de Nínfea aumenta em [Arg3]%, e todos os danos dos Despertadores por veneno aumentam em 10%."
