  AwakerTalent_74108_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O Escudo causado por Ogier é melhorado em [Arg3]%, e a Força causada é melhorada em [Arg4]%. Após cada liberação de Fúria Explosiva, o Escudo causado por Ogier nesta batalha é adicionalmente melhorado em 1% da Defesa."
  },
