  AwakerTalent_74109_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto jogar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·As primeiras 10 cartas de \"Marrom, ataque!\" jogadas a cada turno não adicionarão \"Ajuste de potência de cálculo\".\n·O dano causado por Jenkin aumenta em [Arg3]%."
