  AwakerTalent_74110_TalentDesc_1 = {
    Text = "·Este talento só tem efeito nas fases do \"Capítulo Stella\".\n·A vitalidade, ataque e defesa do Despertador aumentam em [Arg1] %, e o Despertador ganha [Arg2] pontos de S-energia após seu primeiro Despertar de Gnose.\n·Após jogar \"Inspiração\", ganhe poder temporário igual a [Arg3]% do poder de ataque, e acione 1 vez \"Melodia do Momento\", ativando até 5 vezes por turno."
