  AwakerTalent_74111_TalentDesc_1 = {
    Text = "· Este talento é efetivo apenas nos níveis de \"Reinado Astral\".\n· A constituição, ataque e defesa do despertador aumentam em [Arg1] %, e esse despertador ganha [Arg2] pontos de energia chaves de prata após a primeira iluminação.\n· No início da batalha, se houver inimigos \"Fera\", o poder de Casiah nesta batalha aumenta em [Arg3] %. \"Poof\" ativa o efeito de choque posterior de embaralhar o monte de cartas puxadas em sua primeira liberação a cada turno."
  },
