  AwakerTalent_74112_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·Quando Sanga causa Escudo, obtém Dano de tentáculo equivalente a [Arg3]% do valor do Escudo. Quando Sanga libera Fúria Explosiva, recebe adicionalmente [Arg4]% de Aumento de dano de tentáculo."
