  AwakerTalent_74113_TalentDesc_1 = {
    Text = "Este talento só é eficaz nos estágios \"Reinado Astral\".\nA Constituição, Força de ataque e Defesa deste Corpo Desperto +[Arg1]%, e ele ganha [Arg2] Energia de chave no primeiro Despertar do Conhecimento Espiritual.\n\"Chicote da Fúria Dominada\" ganha Preservar e Pronto. Inimigos com intenção de ataque recebem [Arg3]% a mais de Dano ativo de Pandia, aumentando +5% por instância de ataque adicional, até 20%."
