  AwakerTalent_74115_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto jogar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·As primeiras [Arg3] cartas \"Grito agudo, sangue!\" jogadas a cada turno não adicionam \"Ajuste de potência de cálculo\". O dano básico causado por Uvhash aumenta em [Arg4]%, e o efeito dobra quando a vida está abaixo de 25%."
  },
