  AwakerTalent_74117_TalentDesc_1 = {
    Text = "·Este talento só tem efeito nas fases de \"Reinado Astral\".\n·A <awakener>'s <con>, <ataque> e <defesa> aumentam em [Arg1]%, e ao jogar pela primeira vez o <gnosis> <rouse>, ganha [Arg2] pontos de <keyflare>.\n·Após liberar \"Aniquilação\", <Winkle> ganha [Arg3] pontos de <aliemus>, com um tempo de recarga de 3 turnos."
  },
