  AwakerTalent_74118_TalentDesc_1 = {
    Text = "·Este talento é eficaz apenas em estágios de \"Reinado Astral\".\n·A con, atk e def deste Despertador aumentam em [Arg1]%, e ao jogar inicialmente Gnosis Despertar, ganha energia de Chave Prata [Arg2].\n·O dano base de Golias aumenta em [Arg3]%, e \"Domínio da Lâmina\" aumenta temporariamente o dano final de Golias em [Arg4]%. \n·Quando a equipe contém 1/2/3 outros Despertadores de \"Lemúria\", os efeitos de ganho de força de todos os Despertadores são adicionalmente aprimorados em 6%/15%/30%."
  },
