  AwakerTalent_74119_TalentDesc_1 = {
    Text = "· Este talento só é eficaz nos níveis de \"Reinado Astral\".\n· A constituição, ataque e defesa do desperto aumentam em [Arg1] %, e este desperto ganha [Arg2] pontos de energia de chave de prata após a primeira iluminação.\n· Quando Tawil joga cartas pertencentes originalmente a outros despertos na equipe, o dano final, o escudo e a recuperação de HP causados pelo desperto correspondente nesta rodada aumentam em [Arg3] %, e não podem se acumular."
