  AwakerTalent_74120_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O Dano básico causado pelas Cartas de comando de Lotan é aumentado em [Arg3]%. A cada 1 Dano causado por Lotan, o Dano Final causado por Lotan neste turno aumenta 5%, até um máximo de [Arg4]%."
  },
