  AwakerTalent_74123_TalentDesc_1 = {
    Text = "·Este talento só ativa na fase \"Reinado Astral\".\n·A constituição, ataque e defesa deste despertador aumentam em [Arg1] %, e após a primeira ativação do Despertar da Gnose, o despertador ganha [Arg2] pontos de energia da Chave Prata.\n·O dano base causado por \"Golpe\" e \"Corte Preciso\" aumenta em [Arg3] % do escudo ganho neste turno. O dano final de Alva causado aos inimigos do reino \"Caro\" aumenta em [Arg4] %."
  },
