  AwakerTalent_74124_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto jogar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·A Fúria causada por Doll e o efeito de cura da Fúria Explosiva aumentam em [Arg3]%, e para cada Corpo Desperto de outro domínio \"Caos\" na equipe, esse efeito aumenta adicionalmente em [Arg4]%."
  },
  AwakerTalent_74124_TalentDesc_10 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto jogar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·A Fúria e o efeito de cura da Fúria Explosiva causada por Doll aumentam em [Arg3]%, e para cada outro Corpo Desperto do domínio \"Caos\" na equipe, esse efeito aumenta adicionalmente em [Arg4]%."
  },
