  AwakerTalent_74125_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo Estelar\".\n·A Constituição, a Força de ataque e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto realizar o Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia de chave.\n·Celeste gera [Arg3]% mais Dano de tentáculo, e após Disparar a primeira Carta de comando a cada turno, aciona o Talento \"Corneta de Navegação Distante\" 4 vezes adicionais."
