  AwakerTalent_74127_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·Para cada \"Prato Maravilhoso\" na Mão, os efeitos de recuperação de Vida e Escudo causados são aumentados em [Arg4]%, acumulando no máximo 3 camadas. A cada vez que \"Prato Maravilhoso\" é Disparado, o Envenenamento causado por Karen nesta batalha aumenta em [Arg3]%, acumulando no máximo 20 camadas."
  },
