  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O Dano Final do \"golpear\" de Lily é aumentado em [Arg3]%, e o aumento é dobrado na Batalha do Líder. Após receber um ATQ de inimigos \"Ultra\", obtém um efeito de recuperação com Latência de [Arg4]% da Vida perdida neste ATQ. O \"Golpe de recompensa\" desfruta de um bônus de Dano potencializado de [Arg5]% junto ao efeito de Dano aumentado de \"Paciência\"."
  },
  AwakerTalent_74129_TalentDesc_10 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O Dano Final do \"golpear\" de Lily é aumentado em [Arg3]%, e o aumento é dobrado na Batalha do Líder. Após receber um ATQ de inimigos \"Ultra\", obtém um efeito de recuperação com Latência de [Arg4]% da Vida perdida neste ATQ. O \"Golpe de recompensa\" desfruta de um bônus de Dano potencializado de [Arg5]% junto ao efeito de Dano aumentado de \"Paciência\"."
