  AwakerTalent_74130_TalentDesc_1 = {
    Text = "· Este talento é apenas efetivo nos níveis de \"Reinado Astral\".\n· A constituição, ataque e defesa do despertador aumentam em [Arg1] %, e esse despertador ganha [Arg2] pontos de energia de chave prateada após a primeira iluminação.\n· Após Sorel \"devorar\", ganha força temporária de [Arg3] % do poder de ataque, podendo ser acionado no máximo 5 vezes por turno."
  },
