  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·O Envenenamento causado por Faros é aumentado em [Arg3]%. \"A Cidade Perdida de Tempos Antigos\" ordena que todos os tentáculos ataquem 1 vez ao final do turno, mas esses ataques causam apenas [Arg4]% do Dano.\n·Quando há 1/2/3 outros Corpos Despertos de \"Lemuria\" na equipe, Dano potencializado +20%/50%/100%."
