    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1] %, e após este Corpo Desperto jogar a carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de energia da Chave de Prata.\n·O Helot causa um aumento de [Arg3]% no dano final contra inimigos do \"Campo de Neve\". Se o Helot consumiu \"embrião\" neste turno, seu próximo ataque causará um golpe crítico aumentado em [Arg4]%."
