    Text = "·Este talento só tem efeito nas fases do \"Capítulo Stella\".\n·A vitalidade, ataque e defesa do Despertador aumentam em [Arg1] %, e o Despertador ganha [Arg2] pontos de S-energia após seu primeiro Despertar de Gnose.\n·No início da batalha contra o chefe, ganhe resistência à morte igual ao atributo de resistência à morte de Horla [Arg3]%. Após cada desencadeamento da resistência à morte, o efeito do \"Capítulo Caprichoso\" correspondente aumenta em [Arg4]% até o final do turno."
  },
