  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·Este Talento só é eficaz nas Fases do \"Capítulo das Estrelas\".\n·A Constituição, ATQ e Defesa deste Corpo Desperto aumentam [Arg1]%, e após Disparar o Despertar do Conhecimento Espiritual pela primeira vez, este Corpo Desperto obtém [Arg2] pontos de Energia da Chave de Prata.\n·Ao Atualizar as \"Ruínas Cinzentas\", a probabilidade de aparecer desconto é aumentada em [Arg3]%, e a proporção do desconto é aumentada em [Arg4]%.\n·O Dano básico do \"Golpe de pescoço\" é aumentado em [Arg5]%, calculado independentemente do aumento de Dano básico proveniente de Eliminações."
