  AwakerTalent_74138_TalentDesc_1 = {
    Text = "·Este talento só é eficaz no estágio \"reinado astral\".\n·A constituição, ataque e defesa do despertador aumentam em [Arg1]%, e ao usar despertar pela primeira vez, o despertador ganha [Arg2] pontos de energia da chave prateada.\n·Caecus joga a primeira carta de comando a cada turno para restaurar [Arg3]% do hp de sua constituição. Ataques de tentáculos e efeitos de contra-ataque da \"linhagem da heresia\" causam adicionalmente [Arg4]% de dano."
