    Text = "·Este talento só é eficaz nos estágios do \"Capítulo das Estrelas\".\n·A constituição, o ataque e a defesa deste Corpo Desperto aumentam em [Arg1]%, e após este Corpo Desperto jogar uma carta de Despertar do Conhecimento Espiritual pela primeira vez, ele ganha [Arg2] pontos de Energia da Chave de Prata.\n·A recarga da Chave de Prata de Ramona: Desgastada aumenta em [Arg3]%, e no início da batalha, ganhe [Arg4]% de energia da Chave de Prata de Ramona: Desgastada."
  },
