  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Este talento só ativa na fase \"Reinado Astral\".\n·A constituição, ataque e defesa deste despertador aumentam em [Arg1] %, e após a primeira ativação do Despertar da Gnose, o despertador ganha [Arg2] pontos de energia da Chave Prata.\n·O efeito de dano base aplicado por \"Redenção da Agonia\" aumenta o poder de ataque de Pollux em [Arg3] %.\n·Cada pilha de 50 camadas de \"Marca do Pecado\" colocará um \"Coração Sagrado\" na mão.\n·Quando \"Marca do Pecado\" alcança 100 camadas, compre um dos seus próprios \"Cartões de Habilidade\" após a terceira consumição.\n·Ao causar dano, os efeitos de \"Marca do Pecado\" sobre os inimigos da \"Igreja dos Portadores da Luz\" dobram."
  },
