    Text = "Este talento só é eficaz nos estágios \"Reinado Astral\".\nA Constituição, Força de ataque e Defesa deste Corpo Desperto +[Arg1]%, e ele ganha [Arg2] Energia de chave no primeiro Despertar do Conhecimento Espiritual.\nNo início da batalha, todos os inimigos recebem [Arg3]% a mais de Dano de tentáculo. Este efeito é dobrado contra inimigos do \"Mar Profundo\". O Dano ativo causado pelo \"Castigo do Trovão\" a inimigos do \"Mar Profundo\" +[Arg4]%."
