  AwakerTalent_78624_TalentDesc_1 = {
    Text = "· Este talento é efetivo apenas nos níveis de \"Reinado Astral\".\n· A constituição, ataque e defesa do despertador aumentam em [Arg1] %, e esse despertador ganha [Arg2] pontos de energia chaves de prata após a primeira iluminação.\n· Jogar \"Pena Ônix\" não adiciona \"Harmonia da Aritmética\", e a corrosão infligida por \"Penas Purificadoras\" aumenta o poder de ataque de Castor em [Arg3] %.\n· A corrosão que Castor inflige em inimigos da \"Igreja dos Portadores da Luz\" aumenta em [Arg4] %."
