  AwakerTalent_78625_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo Estelar\".\n·A Constituição, a Força de ataque e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e ele ganha [Arg2] Energia de chave após o primeiro Despertar.\n·\"Realidade, também é ilusão\" adicionalmente aumenta o Dano Final causado pela Fúria Explosiva de outros Corpos Despertos neste turno em [Arg3]%, e após o uso, a Aliemus Base de Pickman –5."
