  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Este talento só ativa na fase \"Reinado Astral\".\n·A constituição, ataque e defesa deste despertador aumentam em [Arg1] %, e após a primeira ativação do Despertar da Gnose, o despertador ganha [Arg2] pontos de energia da Chave Prata.\n·A força adquirida por todos os despertadores aumenta em [Arg3] %.\n·Clementine aplica um efeito de sangramento causando [Arg4] % de dano aos alvos ao causar dano a inimigos \"insetóides\". Quando Clementine gera um escudo ou recupera vida pela primeira vez a cada turno, os inimigos \"insetóides\" perdem temporariamente [Arg5] % de sua defesa."
  },
  AwakerTalent_78645_TalentDesc_10 = {
