  AwakerTalent_78911_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo Estelar\".\n·A Constituição, a Força de ataque e a Defesa deste Corpo Desperto aumentam em [Arg1]%, e ele ganha [Arg2] Energia de chave após o primeiro Despertar.\n·Sempre que Murphy: Fauxborn causar Dano, inflige capas de \"Sacrifício\" iguais a [Arg3]% do Dano causado no alvo. O efeito de aumento de capas de \"Cerimônia de Nascimento\" do estado \"Pacto\" é dobrado.\n·Quando houver 1/2/3 outros Corpos Despertos \"Lemurianos\" na equipe: Vida máxima +6%/15%/30%; ganha Escudo do personagem igual a 50%/125%/250% da Defesa de Murphy: Fauxborn após qualquer Corpo Desperto \"Lemuriano\" usar Fúria Explosiva. Limitado a uma vez por turno; não se beneficia de Aumento de Geração de Escudo."
  },
