  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·Após causar dano com uma carta de comando de Clementine, ganhe 1 camada de \"Empatia\".\n·Cada ponto de atributo de recarga da chave de prata fornecido pelo próprio Corpo Desperto de Clementine, Roda do destino e Mystik aumenta a taxa de crítico e o dano crítico em 0,35%.\n·Após o início do Turno Ultra, remova todas as camadas de \"Trauma Psicológico\" e \"Fixação Fóbica\" de todos os inimigos. Para cada camada de \"Trauma Psicológico\" removida de todos os inimigos, ganhe 50 pontos de energia da chave de prata, e para cada camada de \"Fixação Fóbica\" removida de todos os inimigos, faça com que outros Corpos Despertos ganhem 2 pontos de Fúria."
  },
  AwakerTalent_79211_TalentName_1 = {
    Text = "Sentido do Enxame"
  },
  AwakerTalent_79788_TalentDesc_1 = {
    Text = "·Este talento só é eficaz nos estágios do \"Capítulo Estelar\". \n·A constituição, o ataque e a defesa deste Despertado aumentam em [Arg1]%, e após este Despertado jogar uma carta de Despertar da Gnosis pela primeira vez, ele ganha [Arg2] pontos de energia de prata."
