  AwakerTalent_89775_TalentDesc_1 = {
    Text = "Ao Disparar a primeira \"Pluma Negra\" de cada rodada, aplique \"Corrosão\" igual a 840% da Força de ataque de Castor no alvo e ganhe 10 pontos de Fúria.\nPara cada 1% de Dano potencializado que Castor possui, aumente em +1% a \"Corrosão\" Base aplicada.\nApós o fim da batalha, aumente permanentemente em +20% a \"Corrosão\" aplicada por Castor durante esta exploração.\nA \"Corrosão\" aplicada na Batalha do Líder é duplicada.\nApós aplicar \"Corrosão\", o Dano de Castor aumenta em +5% do total de \"Corrosão\" aplicada neste turno.\nO Dano causado por Castor não remove a \"Corrosão\"."
  },
